import 'fake-indexeddb/auto';
import Dexie from 'dexie';
import {it,expect,afterEach,vi} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {newId} from '../src/domain/model';
import {ScopedEditorStore,type EditorImage,type EditorWork} from '../src/sync/editorStore';
import {valueHash,type SyncAck} from '../src/sync/protocol';
import {threeWayMerge} from '../src/sync/merge';
const root='/tmp/shinariokanri-independent-rb09-73a279a/independent',stores:ScopedEditorStore[]=[];
afterEach(async()=>{vi.restoreAllMocks();for(const s of stores.splice(0))await s.delete();});
function proof(id:string,data:unknown){writeFileSync(`${root}/fixtures/${id}.json`,JSON.stringify(data,null,2)+'\n');}
function fixed(){const initial=JSON.parse(readFileSync(`${root}/fixed-fixtures/R9E00.json`,'utf8')).initial;return initial.base as EditorImage;}
async function image(revision='1',expiresAt:string|null=null){return {...fixed(),authorizationRevision:revision,authorizationExpiresAt:expiresAt};}
async function seed(expiresAt:string|null=null){const s=new ScopedEditorStore(newId());stores.push(s);const x=await image('1',expiresAt);await s.receive(x);return {s,x,id:x.documents[0].id};}
async function conflictWithNewAuthority(){const f=await seed();await f.s.saveField(f.x.projectId,f.id,'name','端末A');const op=(await f.s.prepare(f.x.projectId))!,base=op.targets[0].base!,server=structuredClone(base);server.fields.name='サーバーAのcontent2';server.revision='2';const result=threeWayMerge(base,op.targets[0].local,server);if(result.status!=='conflict')throw Error('REVIEW_CONFLICT_NOT_CONSTRUCTED');const ack:SyncAck={schemaVersion:1,operationId:op.operationId,scope:op.scope,operationHash:await valueHash(op),status:'conflict',serverRevision:'2',authorizationRevision:'2',authorizationExpiresAt:null,documents:[server],confirmedDocuments:[server],conflicts:[result.conflict]};await f.s.acknowledge(ack);return {...f,ack,op};}
it('R9E08 a delayed fieldset authority2/content1 cannot replace the content2 already proved by a valid scoped conflict ACK2',async()=>{const f=await conflictWithNewAuthority(),before=await f.s.get(f.x.projectId),delayed={...structuredClone(f.x),authorizationRevision:'2',documents:[structuredClone(f.x.documents[0])]};delayed.contentHash=await valueHash(delayed.documents);let error;try{await f.s.receive(delayed);}catch(e){error=e;}const after=await f.s.get(f.x.projectId);proof('R9E08',{ack:f.ack,before,delayed,after,error:String(error),timeline:'grant2 removes B while server is content1; team_read1/grant2 response captured; owner changes A to content2; editor A operation receives valid conflict ACK content2/grant2; delayed read1/grant2 arrives',expected:'REVISION_CHANGED and no body/base/conflict/evidence rollback'});expect(error).toMatchObject({code:'REVISION_CHANGED'});expect(after).toEqual(before);});
it('R9E09 a valid conflict ACK with current authority2 and confirmed A-only fieldset withdraws B from active writes without losing the original command/conflict evidence',async()=>{const f=await conflictWithNewAuthority(),before=await f.s.get(f.x.projectId),b=f.x.documents[1].id;let error;try{await f.s.saveField(f.x.projectId,b,'name','ACKで撤回を知ったBの新規編集');}catch(e){error=e;}const after=await f.s.get(f.x.projectId);proof('R9E09',{ack:f.ack,before,after,error:String(error),expected:'confirmed scoped ACK2 has only A permitted; old B input may remain recovery evidence but cannot be updated as active editor work'});expect(error).toMatchObject({code:'FORBIDDEN'});expect(after).toEqual(before);expect(JSON.stringify(after)).toContain(f.op.operationId);});
